    54	    @SuppressWarnings("rawtypes")
    55	    private <R extends CustomResource> void registerController(ResourceController<R> controller,
    56	                                                               boolean watchAllNamespaces, Retry retry, String... targetNamespaces) throws OperatorException {
    57	        Class<R> resClass = getCustomResourceClass(controller);
    58	        CustomResourceDefinition crd = getCustomResourceDefinitionForController(controller);
    59	        KubernetesDeserializer.registerCustomKind(getApiVersion(crd), getKind(crd), resClass);
    60	        String finalizer = getDefaultFinalizer(controller);
    61	        MixedOperation client = k8sClient.customResources(CustomResourceDefinitionContext.fromCrd(crd),
    62	                resClass, CustomResourceList.class, getCustomResourceDoneableClass(controller));
    63	        EventDispatcher eventDispatcher = new EventDispatcher(controller,
    64	                finalizer, new EventDispatcher.CustomResourceFacade(client), ControllerUtils.getGenerationEventProcessing(controller));
    65	        EventScheduler eventScheduler = new EventScheduler(eventDispatcher, retry);
    66	        registerWatches(controller, client, resClass, watchAllNamespaces, targetNamespaces, eventScheduler);
    67	    }
