    70	    private <R extends CustomResource> void registerWatches(ResourceController<R> controller, MixedOperation client,
    71	                                                            Class<R> resClass,
    72	                                                            boolean watchAllNamespaces, String[] targetNamespaces, EventScheduler eventScheduler) {
    73	
    74	        CustomResourceOperationsImpl crClient = (CustomResourceOperationsImpl) client;
    75	        if (watchAllNamespaces) {
    76	            crClient.inAnyNamespace().watch(eventScheduler);
    77	        } else if (targetNamespaces.length == 0) {
    78	            client.watch(eventScheduler);
    79	        } else {
    80	            for (String targetNamespace : targetNamespaces) {
    81	                crClient.inNamespace(targetNamespace).watch(eventScheduler);
    82	                log.debug("Registered controller for namespace: {}", targetNamespace);
    83	            }
    84	        }
    85	        customResourceClients.put(resClass, (CustomResourceOperationsImpl) client);
    86	        log.info("Registered Controller: '{}' for CRD: '{}' for namespaces: {}", controller.getClass().getSimpleName(),
    87	                resClass, targetNamespaces.length == 0 ? "[all/client namespace]" : Arrays.toString(targetNamespaces));
    88	    }
