    90	    private CustomResourceDefinition getCustomResourceDefinitionForController(ResourceController controller) {
    91	        String crdName = getCrdName(controller);
    92	        CustomResourceDefinition customResourceDefinition = k8sClient.apiextensions().v1beta1()
    93	                .customResourceDefinitions().withName(crdName).get();
    94	        if (customResourceDefinition == null) {
    95	            throw new OperatorException("Cannot find Custom Resource Definition with name: " + crdName);
    96	        }
    97	        return customResourceDefinition;
    98	    }
